"""ddx-agent adapter command builder for the TerminalBench matrix."""

from __future__ import annotations

from typing import Any

from .base import (
    BaseAdapter,
    BenchmarkProfile,
    CommandSpec,
    InstallSpec,
    empty_telemetry,
    jsonl_objects,
    redact_values,
)


class Agent(BaseAdapter):
    name = "ddx-agent"

    def install(self) -> InstallSpec:
        return InstallSpec(["install", "-m", "0755", "${HARBOR_AGENT_ARTIFACT}", "/installed-agent/ddx-agent"])

    def apply_profile(self, profile: BenchmarkProfile) -> CommandSpec:
        env = {
            "DDX_BENCH_PROVIDER_TYPE": profile.provider.type,
            "DDX_BENCH_PROVIDER_MODEL": profile.provider.model,
            "DDX_BENCH_PROVIDER_BASE_URL": profile.provider.base_url,
            "DDX_BENCH_PROVIDER_API_KEY_ENV": profile.provider.api_key_env,
        }
        if profile.sampling.reasoning:
            env["DDX_BENCH_PROVIDER_REASONING"] = profile.sampling.reasoning
        return CommandSpec(argv=[], env=env, stdin=None)

    def command(self, profile: BenchmarkProfile, prompt: str, workdir: str | None = None) -> CommandSpec:
        applied = self.apply_profile(profile)
        argv = [
            "/installed-agent/ddx-agent",
            "--json",
            "--preset",
            "benchmark",
            "--work-dir",
            workdir or ".",
            "-p",
            prompt,
        ]
        return CommandSpec(argv=argv, env=applied.env, stdin="", cwd=workdir)

    def parse_telemetry(self, stream: str) -> dict[str, Any]:
        telemetry = empty_telemetry()
        for event in jsonl_objects(stream):
            if event.get("type") not in {"session.end", "final"}:
                continue
            data = event.get("data")
            if isinstance(data, dict):
                usage = data.get("usage") or {}
                telemetry["input_tokens"] = usage.get("input") or usage.get("input_tokens")
                telemetry["output_tokens"] = usage.get("output") or usage.get("output_tokens")
                if data.get("status") == "failed":
                    telemetry["process_outcome"] = "harness_crash"
        telemetry["wall_seconds"] = 0.0
        return telemetry

    def redact_secrets(self, text: str, env: dict[str, str], profile: BenchmarkProfile | None = None) -> str:
        values = list(env.values())
        if profile is not None:
            values.extend([
                env.get(profile.provider.api_key_env, ""),
                profile.provider.base_url,
            ])
        return redact_values(text, values)

// Command bench discovers (harness, provider, model) candidates from
// agent config and runs a corpus of small tasks to produce per-task metrics.
package main

import (
	"flag"
	"fmt"
	"os"

	"github.com/DocumentDrivenDX/fizeau/internal/productinfo"
)

func main() {
	os.Exit(run(os.Args[1:]))
}

func run(args []string) int {
	if len(args) == 0 {
		printUsage()
		return 2
	}

	switch args[0] {
	case "discover":
		return cmdDiscover(args[1:])
	case "run":
		return cmdRun(args[1:])
	case "report":
		return cmdReport(args[1:])
	case "profiles":
		return cmdProfiles(args[1:])
	case "matrix":
		return cmdMatrix(args[1:])
	case "matrix-aggregate":
		return cmdMatrixAggregate(args[1:])
	case "help", "-h", "--help":
		printUsage()
		return 0
	default:
		fmt.Fprintf(os.Stderr, "%s: unknown command %q\n", benchCommandName(), args[0])
		printUsage()
		return 2
	}
}

func benchCommandName() string {
	return productinfo.BinaryName + "-bench"
}

func printUsage() {
	fmt.Fprintf(os.Stderr, `Usage: %s <command> [flags]

Commands:
  discover   List discovered (harness, provider, model) candidates
  run        Run corpus against discovered candidates
  report     Render a results file as table, json, or markdown
  profiles   Manage v7 benchmark profiles (subcommand: list)
  matrix     Run the SD-010 harness/profile/task matrix
  matrix-aggregate
             Aggregate matrix cell reports into matrix.json, matrix.md, costs.json

Run '%s <command> -h' for command-specific flags.
`, benchCommandName(), benchCommandName())
}

// resolveWorkDir returns the working directory: --work-dir flag or cwd.
func resolveWorkDir(wd string) string {
	if wd != "" {
		return wd
	}
	d, err := os.Getwd()
	if err != nil {
		return "."
	}
	return d
}

// flagSet creates a FlagSet that writes to stderr with ContinueOnError.
func flagSet(name string) *flag.FlagSet {
	fs := flag.NewFlagSet(name, flag.ContinueOnError)
	fs.SetOutput(os.Stderr)
	return fs
}

